# Hand-written wrapper (NOT generated by savvy-cli). `sz_run_experiment_raw()`
# is the savvy-generated binding, defined in R/000-wrappers.R; this wrapper
# gives it R-native default arguments (savvy has no way to express a non-NULL
# default for a required argument in the generated signature).

#' Run a sezgi experiment spec across algorithms x problems x instances x
#' seeds x budgets.
#'
#' Mirrors py-sezgi's `run_experiment()`: `journal = NULL` runs directly
#' (in parallel or sequentially, per `parallel`); a non-`NULL` `journal`
#' path runs through the checkpoint executor, which resumes from -- and
#' appends to -- an existing journal file at that path.
#'
#' @param spec_toml Experiment spec as TOML. Schema (see
#'   `crates/bench/src/experiment.rs`): top-level `name` (string), `seeds`
#'   (integer array), `budgets` (integer array); one or more `[[algorithms]]`
#'   tables, each with a `name` and either `preset = { kind = "...",
#'   pop_size = ... }` (pop_size optional/ignored for dim-linked presets:
#'   `lshade`, `cmaes_ipop`, `nelder_mead`, `sa`) or `spec_toml = "..."`; one
#'   or more `[[problems]]` tables, each with `suite = "bbob"`, `fid`
#'   (integer), `dim` (integer), `instances` (integer array).
#' @param journal Optional path to a checkpoint journal file (JSONL). When
#'   given, results are loaded from and appended to this file, and re-running
#'   with the same file resumes without re-running completed cells.
#' @param parallel Whether to run in parallel via rayon (default `TRUE`).
#'   Results are bit-identical to the sequential (`FALSE`) run.
#' @param threads Optional rayon thread-pool size (`NULL` uses rayon's
#'   default).
#' @returns A data.frame with one row per run and columns `algo`, `fid`,
#'   `dim`, `instance`, `seed`, `budget`, `best_f`, `f_opt`, `evals`.
#' @export
sz_run_experiment <- function(spec_toml, journal = NULL, parallel = TRUE, threads = NULL) {
  sz_run_experiment_raw(spec_toml, parallel, journal, threads)
}
